const listArtifactsForRelease = `-- name: ListArtifactsForRelease :many
SELECT artifact_id, release_version_id, artifact_role, platform_os, platform_arch, oci_repository, oci_digest, oci_media_type, oci_size_bytes, registry_url, created_at
FROM release_artifacts
WHERE release_version_id = $1
ORDER BY artifact_role, platform_os, platform_arch, artifact_id
`

type ListArtifactsForReleaseParams struct {
	ReleaseVersionID uuid.UUID
}

func (q *Queries) ListArtifactsForRelease(ctx context.Context, arg ListArtifactsForReleaseParams) ([]ReleaseArtifact, error) {
	rows, err := q.db.Query(ctx, listArtifactsForRelease, arg.ReleaseVersionID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReleaseArtifact{}
	for rows.Next() {
		var i ReleaseArtifact
		if err := rows.Scan(
			&i.ArtifactID,
			&i.ReleaseVersionID,
			&i.ArtifactRole,
			&i.PlatformOs,
			&i.PlatformArch,
			&i.OciRepository,
			&i.OciDigest,
			&i.OciMediaType,
			&i.OciSizeBytes,
			&i.RegistryUrl,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

